/// <summary>
/// VendEditInvoice form VendInvoiceInfoTable datasource extension
/// </summary>
[ExtensionOf(formDataSourceStr(VendEditInvoice, VendInvoiceInfoTable))]
final class METVendEditInvoiceFDS_VendInvoiceInfoTable_Extension
{
}

Method.Source:
    /// <summary>
    /// disable edit of the import amount and import tax fields
    /// </summary>
    public void init()
    {
        next init();

        this.object(fieldNum(VendInvoiceInfoTable, ImportedAmount)).allowEdit(false);
        this.object(fieldNum(VendInvoiceInfoTable, ImportedSalesTax)).allowEdit(false);
    }

    /// <summary>
    /// Display method to calculate variance
    /// </summary>
    /// <returns>Variance</returns>
    public display MetVariance metVariance()
    {
        VendInvoiceInfoTable    VendInvoiceInfoTable;

        this.metObserveLine();
        VendInvoiceInfoTable = this.cursor();
        return VendInvoiceInfoTable.displayMetVariance();
    }

    /// <summary>
    /// Display method to calculate GST variance
    /// </summary>
    /// <returns>GST variance</returns>
    public display MetGSTVariance metGSTVariance()
    {
        VendInvoiceInfoTable    VendInvoiceInfoTable;

        this.metObserveLine();
        VendInvoiceInfoTable = this.cursor();
        return VendInvoiceInfoTable.displayMetGSTVariance();
    }

    /// <summary>
    /// Check if variane within tolerance
    /// </summary>
    /// <returns>true/false</returns>
    public display MetVarInTol metVarInTolerance()
    {
        VendInvoiceInfoTable    VendInvoiceInfoTable;

        this.metObserveLine();
        VendInvoiceInfoTable = this.cursor();

        return VendInvoiceInfoTable.displayMETVarInTolerance();
    }

    /// <summary>
    /// Check if claim line exists
    /// </summary>
    /// <returns>Trur/false</returns>
    public display MetClaimExist metHasClaimLines()
    {
        VendInvoiceInfoTable    VendInvoiceInfoTable;

        this.metObserveLine();
        VendInvoiceInfoTable = this.cursor();

        return VendInvoiceInfoTable.displayMETHasClaimLines();
    }

    /// <summary>
    /// Observe VendInvocieInfoLine datasource
    /// </summary>
    public void metObserveLine()
    {
        FormRun         formRun                 = this.formRun();
        FormDataSource  VendInvoiceInfoLine_ds  = formRun.findFirstFormDataSource(tableNum(VendInvoiceInfoLine));

        VendInvoiceInfoLine_ds.observe();
    }

    /// <summary>
    /// Display or hide the custom fields and compare tax group for purchase order to invoice lines.
    /// </summary>
    /// <returns>Integer</returns>
    public int active()
    {
        int ret;

        ret = next active();

        this.displayHideCustomFields();

        VendInvoiceInfoTable vendInvinfoTable = this.cursor();

        if (vendInvinfoTable.METEDIInvoice && vendInvinfoTable.RequestStatus == VendInvoiceRequestStatus::InReview)
        {
            VendInvoiceInfoLine vendInvoiceInfoLine;
            PurchLine purchLine;

            select firstonly RecId from vendInvoiceInfoLine
            exists join purchLine
                where purchLine.RecId == vendInvoiceInfoLine.PurchLineRecId
                && (purchLine.TaxGroup != vendInvoiceInfoLine.TaxGroup || purchLine.TaxItemGroup != vendInvoiceInfoLine.TaxItemGroup);
 
            if (vendInvoiceInfoLine.RecId)
            {
                info("@MET:GSTDoNotMatch");
            }
        }

        return ret;
    }

    /// <summary>
    /// Display or hide the custom fields.
    /// </summary>
    private void displayHideCustomFields()
    {
        FormRun formRun = this.formRun();
        FormControl recCWQty = formRun.design(1).controlName(formControlStr(VendEditInvoice, VendInvoiceInfoLine_METReceiptedCWQuantity));
        FormControl recQty = formRun.design(1).controlName(formControlStr(VendEditInvoice, VendInvoiceInfoLine_METReceiptedQuantity));
        FormControl recUnitPrice = formRun.design(1).controlName(formControlStr(VendEditInvoice, VendInvoiceInfoLine_METReceiptedUnit));
        FormControl recLineNetAmt = formRun.design(1).controlName(formControlStr(VendEditInvoice, VendInvoiceInfoLine_METReceiptedLineNetAmount));
        FormControl priceVar = formRun.design(1).controlName(formControlStr(VendEditInvoice, VendInvoiceInfoLine_METPriceVarianceReal));
        FormControl qtyVar = formRun.design(1).controlName(formControlStr(VendEditInvoice, VendInvoiceInfoLine_METQuantityVariance));
        FormControl priceReason = formRun.design(1).controlName(formControlStr(VendEditInvoice, METeditPriceReasonCode));
        FormControl qtyReason = formRun.design(1).controlName(formControlStr(VendEditInvoice, METeditReasonCode));
        FormControl performMatching = formRun.design(1).controlName(formControlStr(VendEditInvoice, MetPerformMatching));
        FormControl metInvoiceMatching = formRun.design(1).controlName(formControlStr(VendEditInvoice, METInvoiceMatching));

        VendInvoiceInfoTable vendInvoiceInfoTable = this.cursor();

        if (METVendParameters::find().EnableMetcashMatchingLogic && !vendInvoiceInfoTable.isChargeThroughEnabled() && !vendInvoiceInfoTable.isLandedCostEnabled())
        {
            recCWQty.visible(true);
            recQty.visible(true);
            recUnitPrice.visible(true);
            recLineNetAmt.visible(true);
            priceVar.visible(true);
            qtyVar.visible(true);
            priceReason.visible(true);
            qtyReason.visible(true);
            performMatching.visible(true);
            metInvoiceMatching.visible(true);

            FormControl matchStatus = formRun.design(1).controlName(formControlStr(VendEditInvoice, MatchVariance));
            FormControl headerBudgetCheck = formRun.design(1).controlName(formControlStr(VendEditInvoice, VendInvoiceInfoTable_BudgetCheckResult));
            FormControl procurementcategory = formRun.design(1).controlName(formControlStr(VendEditInvoice, PurchParmLine_ProcurementCategory));
            FormControl productRecieptQtyMatch = formRun.design(1).controlName(formControlStr(VendEditInvoice, QuantityMatch));
            FormControl priceMatch = formRun.design(1).controlName(formControlStr(VendEditInvoice, PriceMatch));
            FormControl priceTotalMatch = formRun.design(1).controlName(formControlStr(VendEditInvoice, ExtendedPriceMatch));
            
            if (METVendParameters::find().DisplayHideCustomFields)
            {
                matchStatus.visible(false);
                headerBudgetCheck.visible(false);
                procurementcategory.visible(false);
                productRecieptQtyMatch.visible(false);
                priceMatch.visible(false);
                priceTotalMatch.visible(false);
            }
            else
            {
                matchStatus.visible(true);
                headerBudgetCheck.visible(true);
                procurementcategory.visible(true);
                productRecieptQtyMatch.visible(true);
                priceMatch.visible(true);
                priceTotalMatch.visible(true);
            }
        }
        else
        {
            recCWQty.visible(false);
            recQty.visible(false);
            recUnitPrice.visible(false);
            recLineNetAmt.visible(false);
            priceVar.visible(false);
            qtyVar.visible(false);
            priceReason.visible(false);
            qtyReason.visible(false);
            performMatching.visible(false);
            metInvoiceMatching.visible(false);
        }
    }
